// The keys of the guide's catalogue (guide-catalog.json), without the catalogue: the coach's exercise sheet may name
// any exercise the guide knows (programme.js, knownExercise), and the programme's code loads with the first screen,
// where the 124 kB catalogue stays out (ExerciseList.jsx). Generated by scripts/guide-keys.mjs; guide-keys.test.js
// keeps the two in step. Catalogue keys only, no alias: "lunge" (a counting key the guide names forward_lunge) is not one.
import keys from './guide-keys.json';

const GUIDE_KEYS = new Set(keys);

/** Whether the guide's catalogue holds this key (a Set: "__proto__" and "constructor" are not keys). */
export const isGuideKey = key => typeof key === 'string' && GUIDE_KEYS.has(key);
